% BP detection for scat coef and backscat

names_sc={'BsB_S', 'BsG_S', 'BsR_S'};
break_HAC_scat_BP=change_point_analysis_Def(HAC_rd,names_sc,0.05,'HAC','scattering'); %[output:6602f177] %[output:4ce2e241] %[output:14b0cc4f] %[output:440f55b9]
