T_HAC_bscat_BP=make_table_breakpoints_def(break_HAC_bscat_BP);
%%
%AE131 could be homogenised with CLAP:
% common period= 1.8.1997 - 9.12.2001
Pt=timerange('2019-01-01','2020-01-01');
ratio_med_h=nanmedian(HAC_rd.BaG0_A(Pt)./HAC_rd.Ba30_A(Pt)); %0.99
ratio_STN_h=nanstd(HAC_rd.BaG0_A(Pt)./HAC_rd.Ba30_A(Pt)); % 0.3175 
ratio_mean_h=nanmean(HAC_rd.BaG0_A(Pt)./HAC_rd.Ba30_A(Pt)); %1.0061
ratio_mean=nanmean(HAC_rd.BaG0_A(Pt))/nanmean(HAC_rd.Ba30_A(Pt)); %0.6480
